def decode_alpha(name: str):
    """RLE → 長さ SIZE*SIZE のアルファ配列（0〜255）。不正なら None。"""
    s = _A.get(name)
    if not s:
        return None
    vals = []
    try:
        for tok in s.split(","):
            v, n = tok.split("x")
            vals.extend([min(255, int(v) * 17)] * int(n))
    except ValueError:
        return None
    if len(vals) != SIZE * SIZE:
        return None
    return vals


def make_pixmap(name: str, size: int = SIZE):
    """QPixmap を返す（無ければ None）。"""
    alpha = decode_alpha(name)
    if alpha is None:
        return None
    try:
        from core.compat import QtGui
        img = QtGui.QImage(SIZE, SIZE, QtGui.QImage.Format_ARGB32)
        img.fill(0)
        r, g, b = COLOR
        for y in range(SIZE):
            for x in range(SIZE):
                a = alpha[y * SIZE + x]
                if a:
                    img.setPixel(x, y, (a << 24) | (r << 16) | (g << 8) | b)
        pm = QtGui.QPixmap.fromImage(img)
        if size != SIZE:
            from core.compat import Qt
            pm = pm.scaled(size, size, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        return pm
    except Exception:
        return None


